BEGIN;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM "project_issues") THEN
    RAISE EXCEPTION 'System workflows require a fresh deployment without project issues; existing issues were not modified.';
  END IF;
END $$;
ALTER TABLE "project_issues" DROP CONSTRAINT "project_issues_workflow_version_fkey";
DROP TABLE "project_workflow_versions";
DROP TABLE "project_workflows";
CREATE TABLE "system_workflows" (
  "id" TEXT PRIMARY KEY,
  "type" TEXT NOT NULL,
  "revision" INTEGER NOT NULL DEFAULT 1,
  "draft" JSONB NOT NULL,
  "published_version" INTEGER NOT NULL DEFAULT 1,
  CONSTRAINT "system_workflows_type_check" CHECK ("type" IN ('requirement', 'bug'))
);
CREATE UNIQUE INDEX "system_workflows_type_key" ON "system_workflows"("type");
CREATE TABLE "system_workflow_versions" (
  "id" TEXT PRIMARY KEY,
  "workflow_id" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  "definition" JSONB NOT NULL,
  "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "system_workflow_versions_workflow_id_fkey" FOREIGN KEY ("workflow_id") REFERENCES "system_workflows"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "system_workflow_versions_workflow_id_version_key" ON "system_workflow_versions"("workflow_id", "version");
ALTER TABLE "project_issues" ADD CONSTRAINT "project_issues_workflow_version_id_fkey" FOREIGN KEY ("workflow_version_id") REFERENCES "system_workflow_versions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
UPDATE "departments" SET "permissions" = array_remove("permissions", 'workflow.manage') WHERE 'workflow.manage' = ANY("permissions");
UPDATE "project_members" SET "permissions" = array_remove("permissions", 'workflow.manage') WHERE 'workflow.manage' = ANY("permissions");
